python - <<'PY'
import os, sys, platform, json, tarfile, io, urllib.request

out_dir = os.path.abspath("./gitleaks-bin")
os.makedirs(out_dir, exist_ok=True)
bin_path = os.path.join(out_dir, "gitleaks")
if os.path.exists(bin_path) and os.access(bin_path, os.X_OK):
    print(f"gitleaks already installed at {bin_path}")
    sys.exit(0)

os_name = platform.system().lower()
if os_name.startswith("darwin"):
    os_name = "darwin"
elif os_name.startswith("linux"):
    os_name = "linux"
else:
    raise SystemExit(f"Unsupported OS: {platform.system()}")

arch = platform.machine().lower()
arch_candidates = []
if arch in ("arm64", "aarch64"):
    arch_candidates = ["arm64"]
elif arch in ("x86_64", "amd64"):
    # try both common labels used across releases
    arch_candidates = ["amd64", "x64", "x86_64"]
else:
    # try common possibilities anyway
    arch_candidates = [arch, "amd64", "x64"]

def fetch(url):
    with urllib.request.urlopen(url) as r:
        return r.read()

def pick_asset_from_api():
    try:
        data = fetch("https://api.github.com/repos/gitleaks/gitleaks/releases/latest")
        rel = json.loads(data.decode("utf-8"))
        for asset in rel.get("assets", []):
            name = asset.get("name","").lower()
            if not name.endswith(".tar.gz"): 
                continue
            if os_name in name and any(a in name for a in arch_candidates):
                return asset.get("browser_download_url")
    except Exception as e:
        return None
    return None

def try_fixed_versions():
    # A small set of recent v8 versions known to have prebuilt binaries
    versions = ["v8.33.0","v8.31.2","v8.30.0","v8.29.0","v8.27.0","v8.24.2"]
    for v in versions:
        ver = v.lstrip("v")
        for a in arch_candidates:
            name = f"gitleaks_{ver}_{os_name}_{a}.tar.gz"
            url = f"https://github.com/gitleaks/gitleaks/releases/download/{v}/{name}"
            try:
                return fetch(url)
            except Exception:
                continue
    return None

# Try GitHub API to find matching asset URL
asset_url = pick_asset_from_api()
tar_bytes = None
if asset_url:
    try:
        tar_bytes = fetch(asset_url)
    except Exception:
        tar_bytes = None

# Fallback: try a few fixed versions/arch labels via direct URL construction
if tar_bytes is None:
    tar_bytes = try_fixed_versions()
if tar_bytes is None:
    raise SystemExit("Failed to download a suitable gitleaks binary for this platform.")

# Extract the 'gitleaks' binary from the tarball
with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:gz") as tf:
    member = None
    for m in tf.getmembers():
        base = os.path.basename(m.name)
        if base == "gitleaks" and m.isfile():
            member = m
            break
    if member is None:
        # try best-effort: first regular file named like gitleaks*
        for m in tf.getmembers():
            base = os.path.basename(m.name)
            if base.startswith("gitleaks") and m.isfile() and "." not in base:
                member = m
                break
    if member is None:
        raise SystemExit("Downloaded archive did not contain a 'gitleaks' binary.")
    f = tf.extractfile(member)
    if f is None:
        raise SystemExit("Failed to extract gitleaks binary from archive.")
    with open(bin_path, "wb") as out:
        out.write(f.read())

os.chmod(bin_path, 0o755)
print(f"Installed gitleaks to {bin_path}")
PY
